create table if not exists public.buildpulse_affiliate_accounts(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,code text not null unique check(code ~ '^[A-Z0-9_-]{4,32}$'),status text not null default 'pending' check(status in ('pending','active','paused','rejected')),commission_bps integer not null default 0 check(commission_bps between 0 and 5000),payout_status text not null default 'not_configured',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.buildpulse_affiliate_attributions(id uuid primary key default gen_random_uuid(),affiliate_account_id uuid not null references public.buildpulse_affiliate_accounts(id),visitor_token_hash text not null,destination_path text not null,referrer_host text,landing_at timestamptz not null default now(),expires_at timestamptz not null,converted_at timestamptz,conversion_reference text,commission_amount numeric(14,2),currency text,metadata jsonb not null default '{}'::jsonb);
alter table public.buildpulse_affiliate_accounts enable row level security;alter table public.buildpulse_affiliate_attributions enable row level security;
revoke all on public.buildpulse_affiliate_accounts,public.buildpulse_affiliate_attributions from anon,authenticated;grant all on public.buildpulse_affiliate_accounts,public.buildpulse_affiliate_attributions to service_role;
grant select on public.buildpulse_affiliate_accounts to authenticated;
create policy "affiliate own account read" on public.buildpulse_affiliate_accounts for select to authenticated using ((select auth.uid())=user_id);
create index if not exists idx_bp_aff_attr_account_landing on public.buildpulse_affiliate_attributions(affiliate_account_id,landing_at desc);